head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF09320.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_ISU_CD_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};



/* 총보수,총비용관련 입력체크 */
scwin.fn_checkRt = function() {
    if ($c.stf.getObjectValue(edt_CIS_COST_RT) == "") {
        $c.win.alert("'집합투자업자보수'를 입력하세요.");
        edt_CIS_COST_RT.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_AP_CMP_LP_COST_RT) == "") {
        $c.win.alert("'AP/LP보수'를 입력하세요.");
        edt_AP_CMP_LP_COST_RT.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TRST_COM_COST_RT) == "") {
        $c.win.alert("'신탁회사보수'를 입력하세요.");
        edt_TRST_COM_COST_RT.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TRANSAGNT_COST_RT) == "") {
        $c.win.alert("'일반사무관리회사보수'를 입력하세요.");
        edt_TRANSAGNT_COST_RT.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_MISC_COST_RT) == "") {
        $c.win.alert("'기타비용'을 입력하세요.");
        edt_MISC_COST_RT.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_SYNTH_SWAP_COST_RT) == "") {
        $c.win.alert("'스왑비용'을 입력하세요.");
        edt_SYNTH_SWAP_COST_RT.focus();
        return false;
    }
};



/* 총보수,총비용 계산 */
scwin.fn_calcul = function() {
    scwin.fn_checkRt();
    var pPF_TOT_FEE = 0;
    var pTOT_COST_RT = 0;
    pPF_TOT_FEE = parseFloat($c.stf.getObjectValue(edt_CIS_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_AP_CMP_LP_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_TRST_COM_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_TRANSAGNT_COST_RT));
    pPF_TOT_FEE = pPF_TOT_FEE.toFixed(6);
    $c.stf.setObjectValue(edt_PF_TOT_FEE, pPF_TOT_FEE);
    pTOT_COST_RT = parseFloat(pPF_TOT_FEE) + parseFloat($c.stf.getObjectValue(edt_MISC_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_SYNTH_SWAP_COST_RT));
    pTOT_COST_RT = pTOT_COST_RT.toFixed(6);
    $c.stf.setObjectValue(edt_TOT_COST_RT, pTOT_COST_RT);
};
scwin.fn_CheckForm = function() {
    scwin.fn_checkRt();
    var pPF_TOT_FEE = 0;
    var pTOT_COST_RT = 0;
    pPF_TOT_FEE = parseFloat($c.stf.getObjectValue(edt_CIS_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_AP_CMP_LP_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_TRST_COM_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_TRANSAGNT_COST_RT));
    pPF_TOT_FEE = pPF_TOT_FEE.toFixed(6);
    pTOT_COST_RT = parseFloat(pPF_TOT_FEE) + parseFloat($c.stf.getObjectValue(edt_MISC_COST_RT)) + parseFloat($c.stf.getObjectValue(edt_SYNTH_SWAP_COST_RT));
    pTOT_COST_RT = pTOT_COST_RT.toFixed(6);
    if ($c.stf.getObjectValue(edt_PF_TOT_FEE) != pPF_TOT_FEE) {
        $c.win.alert("입력한 보수값과 현재 '총보수'값이 일치하지 않습니다.\n[계산]버튼을 눌러 합산하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_TOT_COST_RT) != pTOT_COST_RT) {
        $c.win.alert("입력한 보수값과 현재 '총비용'값이 일치하지 않습니다.\n[계산]버튼을 눌러 합산하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txa_MISC_COST_DTL) != "") {
        if (!$c.stf.checkMaxLength(txa_MISC_COST_DTL, 200, "기타비용 상세내역")) {
            txa_MISC_COST_DTL.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txa_SYNTH_COST_DTL) != "") {
        if (!$c.stf.checkMaxLength(txa_SYNTH_COST_DTL, 200, "스왑비용 상세내역")) {
            txa_SYNTH_COST_DTL.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_HPAGE) == "") {
        $c.win.alert("[홈페이지]를 입력하세요.");
        txb_HPAGE.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_HPAGE, 200, "홈페이지")) {
            txb_HPAGE.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_TRST_CALC_PD_CONTN) == "") {
        $c.win.alert("[회계기간]를 입력하세요.");
        txb_TRST_CALC_PD_CONTN.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_TRST_CALC_PD_CONTN, 200, "회계기간")) {
            txb_TRST_CALC_PD_CONTN.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_TRST_DISTR_PAY_BAS_DD_CONTN) == "") {
        $c.win.alert("[분배금 지급기준일]를 입력하세요.");
        txb_TRST_DISTR_PAY_BAS_DD_CONTN.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_TRST_DISTR_PAY_BAS_DD_CONTN, 300, "분배금 지급기준일")) {
            txb_TRST_DISTR_PAY_BAS_DD_CONTN.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txa_PF_PROD_INFO) == "") {
        $c.win.alert("[상품정보(기본정보)]를 입력하세요.");
        txa_PF_PROD_INFO.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txa_PF_PROD_INFO, 4000, "상품정보(기본정보)")) {
            txa_PF_PROD_INFO.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txa_PF_INVSTWARN_CONTN) == "") {
        $c.win.alert("[상품정보(투자유의사항)]를 입력하세요.");
        txa_PF_INVSTWARN_CONTN.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txa_PF_INVSTWARN_CONTN, 4000, "상품정보(투자유의사항)")) {
            txa_PF_INVSTWARN_CONTN.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = "/pf/PfLstinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveNewListingPfSangpumInfoMgr";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo;
    trs_Save.Post();
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=PF_SANGPUM_INFO_MGR_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.lstlst.select.sangpum.info.mgr.condition" + "&{P}param01=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.reset();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    txb_ISU_CD.setValue(parentWin.txb_SearchIsuCd.getValue());
    txb_ISU_NM.setValue(parentWin.txb_SearchIsuNm.getValue());
    scwin.fn_read_sync();
    if (dts_Item.getTotalRow() == 0) {
        dts_Item.insertRow();
        btn_save.src = "../img/btn_save.gif";
        btn_save.setDisabled(false);
        btn_Update.src = "../img/btn_modify_d.gif";
        btn_Update.setDisabled(true);
    } else {
        btn_save.src = "../img/btn_save_d.gif";
        btn_save.setDisabled(true);
        btn_Update.src = "../img/btn_modify.gif";
        btn_Update.setDisabled(false);
    }
    edt_PF_TOT_FEE.focus();
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Update_onclick = function() {
    scwin.fn_update();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    btn_save.src = "../img/btn_save_d.gif";
    btn_save.setDisabled(true);
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.txa_PF_INVSTWARN_CONTN_OnKillFocus = function() {
    edt_PF_TOT_FEE.focus();
};
scwin.btn_calcul_onclick = function() {
    scwin.fn_calcul();
};
